const {test}=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');const {JSDOM,VirtualConsole}=require('jsdom');const root=path.resolve(__dirname,'..');
const active=['index.html','organizacion/index.html','chat/index.html','admin/index.html','efe/index.html','lista-sabados/index.html','campamento/index.html','glosario/index.html','buffet/index.html','perfiles/index.html'];
test('All active module scripts parse and resolve their shared runtime once',()=>{for(const file of active){const html=fs.readFileSync(path.join(root,file),'utf8');const dom=new JSDOM(html);const scripts=[...dom.window.document.querySelectorAll('script')];const core=scripts.filter(x=>x.src.includes('/assets/tnt-core.js'));assert.equal(core.length,1,file+' has one central runtime');const utilities=scripts.findIndex(x=>x.src.includes('tnt-components.js'));assert(utilities>=0&&utilities<scripts.indexOf(core[0]),file+' utilities before core');for(const s of scripts){if(s.src){if(s.getAttribute('src').startsWith('/')&&!s.src.includes('supabase-lite'))assert(fs.existsSync(path.join(root,s.getAttribute('src').split('?')[0])),file+' '+s.src);}else if(s.textContent.trim())require('acorn').parse(s.textContent,{ecmaVersion:'latest',sourceType:s.type==='module'?'module':'script'});}dom.window.close();}});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));async function until(fn){for(let i=0;i<80;i++){if(fn())return;await sleep(15);}assert.fail('UI did not reach expected state');}
async function app(mod,query='',setup=()=>{}){const file={hub:'index.html',organization:'organizacion/index.html',chat:'chat/index.html'}[mod],html=fs.readFileSync(path.join(root,file),'utf8').replace(/<script\b[^>]*>[\s\S]*?<\/script>/g,''),errors=[];const vc=new VirtualConsole();vc.on('jsdomError',e=>{if(!e.message.includes('navigation'))errors.push(e);});const dom=new JSDOM(html,{url:'https://tnt-test.example/__preview__/'+mod+query,runScripts:'outside-only',pretendToBeVisual:true,virtualConsole:vc});const w=dom.window;w.structuredClone=structuredClone;w.matchMedia=()=>({matches:false,addEventListener(){}});w.scrollTo=()=>{};w.HTMLElement.prototype.scrollIntoView=()=>{};w.HTMLDialogElement.prototype.showModal=function(){this.open=true};w.HTMLDialogElement.prototype.close=function(){this.remove()};w.confirm=()=>true;w.eval(fs.readFileSync(path.join(root,'assets/tnt-components.js'),'utf8'));w.eval(fs.readFileSync(path.join(__dirname,'fixtures/runtime.js'),'utf8'));setup(w);w.eval(fs.readFileSync(path.join(root,{hub:'assets/tnt-hub.js',organization:'organizacion/app.js',chat:'chat/app.js'}[mod]),'utf8'));await until(()=>mod==='hub'?w.document.querySelector('.module-card'):mod==='organization'?w.document.querySelector('.org-nav'):w.document.querySelector('[data-thread]'));return{dom,w,d:w.document,errors,close:()=>{w.dispatchEvent(new w.Event('pagehide'));dom.window.close();}};}
