test('Recuperación EFE conserva asistencia y seguimiento sin sobrescribir registros actuales',async()=>{const dom=new JSDOM('<body data-tnt-module="efe"><main id="attendance-app"></main></body>',{url:'https://tnt-test.example/efe/',runScripts:'outside-only'}),w=dom.window,calls=[];let person=0;w.TNTUI={dateKey:()=> '2026-09-29'};w.TNT={sb:{rpc:async(name,args)=>({data:'00000000-0000-4000-8000-'+String(++person).padStart(12,'0'),error:null}),from:table=>({upsert:(rows,opts)=>{calls.push({table,rows,opts});return Promise.resolve({data:rows,error:null});}})},displayName:()=> 'Dai'};const source=fs.readFileSync(path.join(root,'assets/tnt-attendance.js'),'utf8'),start=source.indexOf('TNT.ready.then(');assert(start>0);w.eval(source.slice(0,start)+'window.__legacy={importData,setGroup:id=>S.group=id};})();');w.__legacy.setGroup('group-id');await w.__legacy.importData({people:[{id:'one',name:'Ana',leaderId:'leader-1'},{id:'two',name:'Luz'}],leaders:[{id:'leader-1',name:'Dai'}],months:{'2026-09':{wednesdays:[{date:'2026-09-23',attendance:{one:true,two:false},followups:{one:{status:'talked',updatedBy:'Dai'},two:{status:'closed',updatedBy:'Santi'}}}]}}});assert.equal(calls[0].table,'tnt_efe_wednesday_attendance');assert.equal(calls[0].rows.length,2);assert.equal(calls[0].rows[1].status,'absent');assert.equal(calls[0].opts.ignoreDuplicates,true);assert.equal(calls[1].table,'tnt_efe_followups');assert.equal(calls[1].opts.onConflict,'person_id,group_id,wednesday_date');assert.equal(calls[1].rows.map(x=>x.status).join(','),'contacted,resolved');dom.window.close();});

