async function inlinePage(file,setup=()=>{},actualCore=false){const source=fs.readFileSync(path.join(root,file),'utf8'),content=source.replace(/<script\b[^>]*>[\s\S]*?<\/script>/g,''),vc=new VirtualConsole(),errors=[];vc.on('jsdomError',e=>{if(!e.message.includes('navigation'))errors.push(e.message);});const dom=new JSDOM(content,{url:'https://tnt-test.example/'+file,runScripts:'outside-only',pretendToBeVisual:true,virtualConsole:vc}),w=dom.window;w.structuredClone=structuredClone;w.matchMedia=()=>({matches:false});w.scrollTo=()=>{};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.eval(fs.readFileSync(path.join(root,'assets/tnt-components.js'),'utf8'));w.eval(fs.readFileSync(path.join(__dirname,'fixtures/runtime.js'),'utf8'));w.TNT.sheet=w.TNTUI.modal;setup(w);if(actualCore){const sb=w.TNT.sb;w.supabase={createClient:()=>sb};w.eval(fs.readFileSync(path.join(root,'assets/tnt-core.js'),'utf8'));}const html=new JSDOM(source);for(const s of html.window.document.querySelectorAll('script:not([src])'))if(s.textContent.trim())w.eval(s.textContent);html.window.close();return {dom,w,d:w.document,errors,close:()=>dom.window.close()};}

