test('Perfiles respeta permiso de lectura y Atrás cierra primero la edición',async()=>{const a=await inlinePage('perfiles/datos/index.html',w=>{w.TNT.isAdmin=false;w.TNT.grants=[{module:'perfiles',scope:'*',enabled:true,access_level:'view'}];w.__fixtureDB.perfiles_registros=[{id:'profile-one',nombre:'Ana',apellido:'Paz',fecha_nacimiento:'2005-03-02',genero:'Mujer',telefono:'1112345678',creado_en:'2026-09-29T12:00:00Z'}];});try{a.w.eval(fs.readFileSync(path.join(root,'perfiles/datos/admin.js'),'utf8'));await until(()=>a.d.querySelector('[data-view-id]'));assert.equal(a.d.querySelector('#dashboardView').hidden,false);a.d.querySelector('[data-view-id]').click();assert(a.d.querySelector('#editProfileBtn').hidden);assert(a.d.querySelector('#deleteProfileBtn').hidden);a.w.TNT.grants[0].access_level='edit';a.w.history.back();await until(()=>!a.d.querySelector('#detailSheet').classList.contains('open'));a.d.querySelector('[data-view-id]').click();a.d.querySelector('#editProfileBtn').click();assert(a.d.querySelector('#editSheet').classList.contains('open'));a.w.history.back();await until(()=>!a.d.querySelector('#editSheet').classList.contains('open'));assert(a.d.querySelector('#detailSheet').classList.contains('open'));a.w.history.back();await until(()=>!a.d.querySelector('#detailSheet').classList.contains('open'));assert.deepEqual(a.errors,[]);}finally{a.close();}});
test('Buffet usa la Cuenta TNT y permite consultar jornadas originales con lectura',async()=>{const a=await inlinePage('buffet/index.html',w=>{w.supabase={createClient:()=>{throw Error('No debe crear cliente externo')}};w.TNT.isAdmin=false;w.TNT.grants=[{module:'buffet',scope:'*',enabled:true,access_level:'view'}];w.__fixtureDB.tnt_shifts=[{id:'old-shift',shift_date:'2026-09-19',status:'open'}];});try{await until(()=>a.d.querySelector('#shift-history'));await until(()=>a.d.querySelector('.buffet-readonly'));assert(a.d.querySelector('#create-shift').disabled);a.d.querySelector('#shift-history').click();await until(()=>a.d.querySelector('#buffet-date'));a.d.querySelector('#buffet-date').value='2026-09-19';a.d.querySelector('#load-buffet-date').click();await until(()=>a.d.querySelector('#shift-label').textContent.includes('19/09/2026'));assert(a.d.querySelector('.buffet-readonly'));assert.deepEqual(a.errors,[]);}finally{a.close();}});
test('Una prédica conserva el archivo fallido y no duplica el borrador al reintentar',async()=>{const a=await inlinePage('glosario/index.html',w=>{w.eval(fs.readFileSync(path.join(root,'assets/tnt-editor.js'),'utf8'));w.TNT.sb.storage.from=()=>({upload:async()=>({error:{message:'Sin conexión'}}),remove:async()=>({})});});try{await until(()=>a.d.querySelector('[data-nav=create]'));a.d.querySelector('[data-nav=create]').click();a.d.querySelector('#title').value='Prueba';const input=a.d.querySelector('#file'),file=new a.w.File(['documento'],'predica.txt',{type:'text/plain'});file.text=async()=> 'Contenido conservado';Object.defineProperty(input,'files',{value:[file]});input.dispatchEvent(new a.w.Event('change'));await until(()=>a.d.querySelector('.tnt-editor-content')?.textContent==='Contenido conservado');a.d.querySelector('#title').value='Prueba';a.d.querySelector('[data-save=draft]').click();await until(()=>a.d.querySelector('.toast')?.textContent.includes('falta subir el archivo'));assert.equal(a.w.__fixtureDB.sermons.length,1);assert(a.d.querySelector('.tnt-editor-content').textContent.includes('Contenido conservado'));a.w.TNT.sb.storage.from=()=>({upload:async()=>({data:{}}),remove:async()=>({})});a.d.querySelector('[data-save=draft]').click();a.d.querySelector('[data-save=draft]').click();await until(()=>a.w.__fixtureDB.sermon_files?.length===1);assert.equal(a.w.__fixtureDB.sermons.length,1);assert.deepEqual(a.errors,[]);}finally{a.close();}});

test('Calendario y resumen excluyen horarios y tareas de sábados cancelados',async()=>{const setup=w=>{w.__fixtureDB.tnt_events[0].status='cancelled';};const a=await app('organization','?view=calendar',setup);try{assert(!a.d.querySelector('.agenda-list .activity-card'));assert(!a.d.body.textContent.includes('Bienvenida & conexión'));a.d.querySelector('[data-view=my]').click();assert(!a.d.querySelector('[data-task-open]'));assert.deepEqual(a.errors,[]);}finally{a.close();}const b=await app('hub','',setup);try{assert(!b.d.body.textContent.includes('Preparar la merienda'));assert(!b.d.querySelector('.attention-card [href*=task]'));assert.deepEqual(b.errors,[]);}finally{b.close();}});
test('Una confirmación personalizada se cierra con Atrás sin cerrar la tarea',async()=>{const a=await app('organization','?view=activities');try{a.d.querySelector('.encounter-card').click();a.d.querySelector('#modal .activity-card').click();await until(()=>a.d.querySelector('#deleteTask'));a.d.querySelector('#deleteTask').click();assert(a.d.querySelector('dialog.tnt-question'));a.w.history.back();await until(()=>!a.d.querySelector('dialog.tnt-question'));assert(a.d.querySelector('#deleteTask'));assert(a.w.__fixtureDB.tnt_tasks.length===4);assert.deepEqual(a.errors,[]);}finally{a.close();}});
test('Elegir sugerencia deja visible el formulario editable y conserva Atrás',async()=>{const a=await app('organization','?view=activities',w=>{w.__fixtureDB.tnt_templates=[{id:'template',kind:'saturday',name:'Sábado'}];w.__fixtureDB.tnt_template_items=[{id:'idea',template_id:'template',title:'Saludo breve',task_type:'simple',duration_minutes:5}];});try{a.d.querySelector('.encounter-card').click();a.d.querySelector('#suggestTask').click();a.d.querySelector('[data-suggest]').click();await until(()=>a.d.querySelector('#taskForm'));assert.equal(a.d.querySelector('.tnt-overlay'),null);assert.equal(a.d.querySelector('#taskForm').elements.title.value,'Saludo breve');a.w.history.back();await until(()=>!a.d.querySelector('#taskForm'));assert(a.d.querySelector('.encounter-card'));assert.deepEqual(a.errors,[]);}finally{a.close();}});

test('Plantillas de logística conservan presupuesto, enlace y pasos concretos',async()=>{const a=await app('organization','?view=templates',w=>{w.__fixtureDB.tnt_templates=[{id:'merch-type',kind:'event',name:'Congreso'}];});try{a.d.querySelector('[data-template-edit]').click();a.d.querySelector('#addTplItem').click();const f=a.d.querySelector('#tplItemForm');f.elements.title.value='Equipo Merch';f.elements.type.value='logistics';f.elements.type.dispatchEvent(new a.w.Event('change'));assert.equal(f.querySelector('[data-template-budget]').hidden,false);f.elements.budget.value='15000';f.elements.reference.value='https://example.com/catalogo';f.elements.description.value='Preparar los pedidos y contar stock';f.elements.checklist.value='Contar stock\nArmar pedidos';f.dispatchEvent(new a.w.Event('submit',{bubbles:true,cancelable:true}));await until(()=>a.w.__fixtureDB.tnt_template_items.length===1);const item=a.w.__fixtureDB.tnt_template_items[0];assert.equal(item.task_type,'logistics');assert.equal(item.budget_estimated,15000);assert.equal(item.reference_url,'https://example.com/catalogo');assert.equal(item.checklist.length,2);assert.deepEqual(a.errors,[]);}finally{a.close();}});
test('Atrás en Glosario vuelve del libro al mapa antes de salir del módulo',async()=>{const a=await inlinePage('glosario/index.html',w=>{w.__fixtureDB.bible_books=[{id:1,name:'Génesis',testament:'OT',category:'Pentateuco'}];});try{await until(()=>a.d.querySelector('#books'));a.d.querySelector('#books').click();a.d.querySelector('[data-book]').click();assert(a.d.querySelector('#bd'));a.w.history.back();await until(()=>!a.d.querySelector('#bd'));assert(a.d.querySelector('#bm'));a.w.history.back();await until(()=>!a.d.querySelector('#bm'));assert(a.d.querySelector('#books'));assert.deepEqual(a.errors,[]);}finally{a.close();}});

test('Sábados carga personas de TNT sin pedir clave ni conectar otra base',async()=>{const a=await inlinePage('lista-sabados/index.html',w=>{w.__fixtureDB.tnt_saturday_members=w.__fixtureDB.tnt_people.map(p=>({person_id:p.id,active:true}));w.__fixtureDB.tnt_saturday_attendance=[];});try{a.w.eval(fs.readFileSync(path.join(root,'assets/tnt-attendance.js'),'utf8'));await until(()=>a.d.querySelector('.att-person'));assert.equal(a.d.querySelectorAll('.att-person').length,a.w.__fixtureDB.tnt_people.length);assert.equal(a.d.querySelector('#att-import'),null);assert(!a.d.body.textContent.includes('Recuperar datos originales'));assert(!a.d.querySelector('input[type=password]'));assert.deepEqual(a.errors,[]);}finally{a.close();}});
